var n=`0870-aloo-keema`;var a=`world-0870`;var i=`PK`;var s=`south-asia`;var o=4;var r=43;var g={en:`Aloo Keema`,ua:`Алу кіма`};var l={en:`Aloo Keema is a Pakistan dish made with ground beef, yellow onion, ginger-garlic paste, potato. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Алу кіма, страва кухні країни Пакистан. Основні складники: яловичий фарш, жовта цибуля, імбирно-часникова паста, картопля. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var m=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`ground-beef`,650,`g`],[`canola-oil`,48,`ml`],[`yellow-onion`,200,`g`],[`ginger-garlic-paste`,25,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 28 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 28 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:28,i:[[`potato`,490,`g`],[`tomato`,300,`g`],[`water`,250,`ml`],[`garam-masala`,7,`g`],[`ground-turmeric`,4,`g`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,20,`g`]]}];var d={slug:n,id:a,country:`PK`,region:s,servings:4,minutes:43,title:g,text:l,steps:m};export{i as country,d as default,a as id,r as minutes,s as region,o as servings,n as slug,m as steps,l as text,g as title};